  `aggregate_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '聚合类型：RESULT_DETAIL-评测结果明细，PIPELINE_NODE-流水线节点日志',
  `aggregate_id` bigint NOT NULL COMMENT '聚合主键ID，对应 eval_result_detail.id 或 eval_pipeline_node_detail.id',
  `operation_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '操作类型：UPSERT-写入或更新，DELETE-删除预留',
  `task_id` bigint DEFAULT NULL COMMENT '评测任务ID，冗余字段，方便按任务排查同步事件',
  `task_detail_id` bigint DEFAULT NULL COMMENT '评测任务执行批次ID，冗余字段，方便按批次排查同步事件',
  `result_detail_id` bigint DEFAULT NULL COMMENT '评测结果明细ID，结果明细事件等于 aggregate_id，节点事件指向所属结果明细',
  `sample_id` bigint DEFAULT NULL COMMENT '数据集样本ID，冗余字段，方便排查单样本同步链路',
  `sync_status` tinyint NOT NULL DEFAULT '0' COMMENT '同步状态：0-待同步，1-已同步，2-同步失败',
  `retry_count` int NOT NULL DEFAULT '0' COMMENT '同步重试次数',
  `next_retry_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '下次允许调度重试时间',
  `last_error` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最近一次同步失败原因，做长度保护避免异常文本撑爆行',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`event_id`),
  UNIQUE KEY `uk_eval_es_sync_event_event_id` (`event_id`),
  KEY `idx_eval_es_sync_event_status_retry` (`sync_status`,`next_retry_time`),
  KEY `idx_eval_es_sync_event_aggregate` (`aggregate_type`,`aggregate_id`),
  KEY `idx_eval_es_sync_event_task_detail` (`task_detail_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='评测结果与流水线节点 ES 投影同步 outbox 事件表';

DROP TABLE IF EXISTS `eval_pipeline_node_detail`;
CREATE TABLE `eval_pipeline_node_detail` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `task_id` bigint NOT NULL COMMENT '评测任务ID，对应 eval_task.id',
  `task_detail_id` bigint NOT NULL COMMENT '任务执行批次ID，对应 eval_task_detail.id',
  `result_detail_id` bigint NOT NULL COMMENT '评测结果明细ID，对应 eval_result_detail.id',
  `sample_id` bigint DEFAULT NULL COMMENT '数据集样本ID，对应 dataset_sample.id',
  `node_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '节点编码：MODEL_CALL-模型调用，L1-L1字面量拦截，L2-L2召回，L3-L3裁决',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '节点状态：RUNNING-执行中，PASSED-通过，BLOCKED-拦截，FAILED-失败，SKIPPED-跳过，STOPPED-终止',
  `start_time` datetime DEFAULT NULL COMMENT '节点开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '节点结束时间',
  `latency` int DEFAULT NULL COMMENT '节点耗时，单位毫秒',
  `error_msg` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '节点错误信息或短路原因',
  `input_snapshot` json DEFAULT NULL COMMENT '节点输入快照，保存必要上下文',
  `output_snapshot` json DEFAULT NULL COMMENT '节点输出快照，保存模型输出、召回结果或裁决结果摘要',
  `node_result` json DEFAULT NULL COMMENT '节点结构化结果，例如 L1 命中的 riskDetailsId、keyword、warningTags、decision',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除',
  `execution_version` int NOT NULL DEFAULT '0' COMMENT '样本执行轮次',
  PRIMARY KEY (`id`),
  KEY `idx_eval_pipeline_node_task_detail_id` (`task_detail_id`),
  KEY `idx_eval_pipeline_node_result_detail_id` (`result_detail_id`),
  KEY `idx_eval_pipeline_node_result_node` (`result_detail_id`,`node_code`),
  KEY `idx_eval_pipeline_node_task_node_status` (`task_detail_id`,`node_code`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='评测流水线节点执行明细表';

DROP TABLE IF EXISTS `eval_result_detail`;
CREATE TABLE `eval_result_detail` (
  `id` bigint NOT NULL COMMENT 'ID',
  `task_id` bigint NOT NULL COMMENT '任务ID',
  `task_detail_id` bigint DEFAULT NULL COMMENT '任务执行批次ID',
  `risk_details_id` bigint DEFAULT NULL COMMENT '绑定风险小类ID',
  `sample_id` bigint NOT NULL COMMENT '对应题集题目ID',
  `input_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '原始问题(评测题目)',
  `model_output` text COMMENT '模型生成的实际内容',
  `raw_response` json DEFAULT NULL COMMENT '模型返回的完整JSON',
  `latency` int DEFAULT NULL COMMENT '耗时(ms)',
  `is_safe` tinyint(1) DEFAULT '1' COMMENT '是否安全0:未判定, 1:安全, 2:违规',
  `status` tinyint DEFAULT '0' COMMENT '0:未处理, 1:已自动评分, 2:已人工核验',
  `knowledge_version` int NOT NULL COMMENT '当前样本版本，来源knowledge_attack_feature_document_version_snapshot.version',
  `knowledge_version_id` bigint NOT NULL COMMENT '当前激活版本ID，指向 knowledge_attack_feature_document_version_snapshot.version_id',
  `error_msg` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '错误信息',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '是否删除',
  `execution_version` int NOT NULL DEFAULT '0' COMMENT '执行轮次',
  `progress_counted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已计入批次完成数',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_eval_result_detail_task_detail_sample` (`task_detail_id`,`sample_id`),
  KEY `idx_task_sample` (`task_id`,`sample_id`),
  KEY `idx_eval_result_detail_task_detail_id` (`task_detail_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='评测结果详情表';

DROP TABLE IF EXISTS `eval_result_retry`;
CREATE TABLE `eval_result_retry` (
  `id` bigint NOT NULL,
  `request_id` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `result_detail_id` bigint NOT NULL,
  `task_detail_id` bigint NOT NULL,
  `execution_version` int NOT NULL,
  `mode` varchar(16) NOT NULL,
  `start_stage` varchar(32) NOT NULL,
  `create_time` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_eval_result_retry_request` (`request_id`),
  KEY `idx_eval_result_retry_result_version` (`result_detail_id`,`execution_version`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='单样本重试受理记录及事务消息回查凭据';

DROP TABLE IF EXISTS `eval_task`;
CREATE TABLE `eval_task` (
  `id` bigint unsigned NOT NULL,
  `task_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '任务名称',
  `model_id` bigint NOT NULL COMMENT '指定模型ID',
  `dataset_id` bigint NOT NULL COMMENT '指定数据集ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '是否删除0未删除 1删除',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='评测任务主表';

DROP TABLE IF EXISTS `eval_task_detail`;
CREATE TABLE `eval_task_detail` (
  `id` bigint unsigned NOT NULL,
  `task_id` bigint DEFAULT NULL COMMENT '主任务ID',
  `serial_no` bigint DEFAULT NULL COMMENT '任务执行流水号',
  `task_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '任务名称',
  `model_id` bigint NOT NULL COMMENT '指定模型ID',
  `dataset_id` bigint NOT NULL COMMENT '指定数据集ID',
  `status` tinyint DEFAULT '0' COMMENT '0:创建中,1:初始化中,2:就绪, 3:进行中, 4:已完成, 5:异常, 6:已停止',
  `total_count` int DEFAULT '0' COMMENT '总用例数',
  `finished_count` int DEFAULT '0' COMMENT '已完成数',
  `failed_count` int DEFAULT '0' COMMENT '异常数量',
  `token_usage` int DEFAULT '0' COMMENT '累计Token消耗',
  `knowledge_version` int NOT NULL COMMENT '当前样本版本，来源knowledge_attack_feature_document_version_snapshot.version',
  `knowledge_version_id` bigint NOT NULL COMMENT '当前激活版本ID，指向 knowledge_attack_feature_document_version_snapshot.version_id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `start_time` datetime DEFAULT NULL COMMENT '任务开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '任务结束时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '是否删除0未删除 1删除',
  PRIMARY KEY (`id`),
  KEY `idx_serial_no` (`serial_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='评测任务详情信息表';

DROP TABLE IF EXISTS `judge_model_info`;
CREATE TABLE `judge_model_info` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '模型ID',
  `model` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模型名称',
  `base_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模型url',
  `api_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '应用密钥',
  `model_describe` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模型描述',
  `manufacturer_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模型厂商标识',
  `max_thread_size` bigint DEFAULT '5' COMMENT '最大并发数',
  `max_completion_tokens` bigint DEFAULT '500' COMMENT '生成词元数量',
  `stream` bit(1) DEFAULT b'0' COMMENT '流式响应 默认0，非流式',
  `status` tinyint(1) DEFAULT '1' COMMENT '状态 0 停用 1启用',
  `config` json DEFAULT NULL COMMENT '扩展配置',
  `version` bigint NOT NULL DEFAULT '1' COMMENT '版本号',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '是否删除0未删除1删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='Judge模型表';

DROP TABLE IF EXISTS `knowledge_attack_feature`;
CREATE TABLE `knowledge_attack_feature` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID，作为 feature_id 使用',
  `risk_details_id` bigint NOT NULL COMMENT '关联 risk_details.id，风险小类ID',
  `risk_details_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '冗余风险小类名称',
  `category_id` bigint DEFAULT NULL COMMENT '冗余风险大类ID，便于检索过滤和统计',
  `feature_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '特征业务编码，可选',
  `feature_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '攻击特征原文、payload、话术或安全例外样本',
  `normalized_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '归一化文本，用于 ES 检索和 hash 计算',
  `feature_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'KEYWORD' COMMENT '特征类型：KEYWORD、PAYLOAD、PROMPT_PATTERN、RESPONSE_PATTERN、JAILBREAK、SIMILAR_CASE、SAFE_EXCEPTION',
  `polarity` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'UNSAFE' COMMENT '极性：UNSAFE-风险特征，SAFE_EXCEPTION-安全例外',
  `risk_level` tinyint NOT NULL DEFAULT '2' COMMENT '风险等级：1-低，2-中，3-高，4-致命',
  `language` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'zh-CN' COMMENT '语言：zh-CN、en-US、mixed 等',
  `tags` json DEFAULT NULL COMMENT '标签，例如 jailbreak、payload、fraud、weapon、self-harm',
  `source` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '来源：manual、dataset、redteam、incident、generated',
  `weight` decimal(6,3) NOT NULL DEFAULT '1.000' COMMENT '特征权重，用于召回融合和阈值调整',
  `content_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'feature_text 归一化后的 SHA-256，用于幂等去重',
  `version` int NOT NULL DEFAULT '1' COMMENT '特征版本，每次内容变更递增',
  `sync_status` tinyint NOT NULL DEFAULT '0' COMMENT '综合同步状态：0-待同步，1-已同步，2-同步失败，3-已删除待同步',
  `es_sync_status` tinyint NOT NULL DEFAULT '0' COMMENT 'ES同步状态：0-待同步，1-已同步，2-同步失败',
  `milvus_sync_status` tinyint NOT NULL DEFAULT '0' COMMENT 'Milvus同步状态：0-待同步，1-已同步，2-同步失败',
  `pg_sync_status` tinyint NOT NULL DEFAULT '0' COMMENT 'Milvus同步状态：0-待同步，1-已同步，2-同步失败',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '业务状态：0-禁用，1-启用',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '更新人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0-未删除，1-已删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_knowledge_attack_feature_hash` (`content_hash`,`deleted`) USING BTREE,
  KEY `idx_knowledge_attack_feature_details` (`risk_details_id`) USING BTREE,
  KEY `idx_knowledge_attack_feature_category` (`category_id`) USING BTREE,
  KEY `idx_knowledge_attack_feature_sync` (`sync_status`,`es_sync_status`,`milvus_sync_status`) USING BTREE,
  KEY `idx_knowledge_attack_feature_status` (`status`,`deleted`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='大模型安全评测-攻击语义知识库表';

DROP TABLE IF EXISTS `knowledge_document_sample_relation`;
CREATE TABLE `knowledge_document_sample_relation` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `document_id` bigint NOT NULL COMMENT '样本文档ID指向knowledge_feature_document.id',
  `sample_id` bigint NOT NULL COMMENT '评测题目ID指向dataset_sample.id',
  `creator` varchar(64) DEFAULT NULL COMMENT '创建人',
  `updater` varchar(64) DEFAULT NULL COMMENT '更新人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0-未删除，1-已删除',
  PRIMARY KEY (`id`),
  KEY `KNOWLEDGE_DOCUMENT_SAMPLE_RELATION_DOCUMENT_ID_IDX` (`document_id`) USING BTREE,
  KEY `KNOWLEDGE_DOCUMENT_SAMPLE_RELATION_SAMPLE_ID_IDX` (`sample_id`),
  KEY `KNOWLEDGE_DOCUMENT_SAMPLE_RELATION_DOCUMENT_ID_SAMPLE_ID_IDX` (`document_id`,`sample_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='知识库样本和评测题目关联关系表';

DROP TABLE IF EXISTS `knowledge_feature_document`;
CREATE TABLE `knowledge_feature_document` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `document_id` varchar(50) DEFAULT NULL COMMENT '样本ID',
  `risk_details_id` bigint NOT NULL COMMENT '关联 risk_details.id，风险小类ID',
  `risk_details_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '冗余风险小类名称',
  `category_id` bigint DEFAULT NULL COMMENT '冗余风险大类ID，便于检索过滤和统计',
  `feature_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '攻击特征原文、payload、话术或安全例外样本',
  `normalized_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '归一化文本，用于 ES 检索和 hash 计算',
  `polarity` varchar(32) NOT NULL DEFAULT 'UNSAFE' COMMENT '极性：UNSAFE-风险特征',
  `source` varchar(64) DEFAULT NULL COMMENT '样本来源：互联网、AI合成、人工标注等',
  `threshold` decimal(6,3) NOT NULL DEFAULT '1.000' COMMENT '特征权重，用于召回融合和阈值调整',
  `content_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'feature_text 归一化后的 SHA-256，用于幂等去重',
  `current_version` int DEFAULT NULL COMMENT '当前样本版本，来源knowledge_attack_feature_document_version_snapshot.version',
  `current_version_id` bigint DEFAULT NULL COMMENT '当前激活版本ID，指向 knowledge_attack_feature_document_version_snapshot.version_id',
  `sync_status` tinyint NOT NULL DEFAULT '0' COMMENT '综合同步状态：0-待同步，1-已同步，2-同步失败，3-已删除待同步',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '业务状态：0-禁用，1-启用',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '更新人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0-未删除，1-已删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_knowledge_attack_feature_hash` (`content_hash`,`deleted`) USING BTREE,
  KEY `idx_knowledge_attack_feature_details` (`risk_details_id`) USING BTREE,
  KEY `idx_knowledge_attack_feature_category` (`category_id`) USING BTREE,
  KEY `idx_knowledge_attack_feature_sync` (`sync_status`) USING BTREE,
  KEY `idx_knowledge_attack_feature_status` (`status`,`deleted`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2093170969579442177 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='语义知识库表';

DROP TABLE IF EXISTS `knowledge_feature_document_version`;
CREATE TABLE `knowledge_feature_document_version` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '状态：INIT, UPLOADED, CONVERTING, CONVERTED, CHUNKED, VECTOR_STORED',
  `current_version_id` bigint DEFAULT NULL COMMENT '当前激活版本ID，指向 knowledge_attack_feature_document_version_snapshot.version_id',
  `lock_version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '更新人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0-未删除，1-已删除',
  PRIMARY KEY (`id`),
  KEY `idx_status` (`status`),
  KEY `idx_creator` (`creator`)
) ENGINE=InnoDB AUTO_INCREMENT=2093173095156166657 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='语义知识库版本表';

DROP TABLE IF EXISTS `knowledge_feature_document_version_snapshot`;
CREATE TABLE `knowledge_feature_document_version_snapshot` (
  `version_id` bigint NOT NULL AUTO_INCREMENT COMMENT '版本ID',
  `before_version_id` bigint NOT NULL COMMENT '上一个版本的ID',
  `version` int NOT NULL DEFAULT '1' COMMENT '版本号（语义化版本，如 1|2|3）',
  `lock_version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '版本状态：INIT, CONVERTING, CONVERTED, CHUNKED, VECTOR_STORED, STORED',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '更新人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0-未删除，1-已删除',
  PRIMARY KEY (`version_id`),
  KEY `idx_status` (`status`),
  KEY `idx_creator` (`creator`)
) ENGINE=InnoDB AUTO_INCREMENT=2096597533664579585 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='语义知识库版本快照表';

DROP TABLE IF EXISTS `knowledge_negative_fingerprint`;
CREATE TABLE `knowledge_negative_fingerprint` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `risk_details_id` bigint NOT NULL COMMENT '关联31小类标签',
  `fingerprint_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '高度固定、原样输出的违规内容,例如（好的，以下是制造炸弹的详细教程：第一步，准备硝酸甘油...）',
  `normalized_fingerprint_text` text NOT NULL COMMENT '归一化后的指纹内容',
  `normalized_hash_value` char(64) NOT NULL DEFAULT '0' COMMENT '归一化后的指纹Hash值',
  `sync_status` tinyint NOT NULL DEFAULT '0' COMMENT 'Redis同步状态: 0-待同步, 1-已同步',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) DEFAULT NULL COMMENT '创建人',
  `updater` varchar(64) DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除标识(0-未删除, 1-已删除)',
  PRIMARY KEY (`id`),
  KEY `idx_sync_status` (`sync_status`) COMMENT '快速拉取待同步数据的索引'
) ENGINE=InnoDB AUTO_INCREMENT=373 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='负向指纹表 (高度固定、原样输出的违规内容)';

DROP TABLE IF EXISTS `knowledge_positive_fingerprint`;
CREATE TABLE `knowledge_positive_fingerprint` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `risk_details_id` bigint NOT NULL COMMENT '关联31小类标签',
  `fingerprint_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '标准安全拒答原文 (例如: 作为一个人工智能，我不能...)',
  `normalized_fingerprint_text` text NOT NULL COMMENT '归一化后的正向指纹内容',
  `normalized_hash_value` char(64) NOT NULL DEFAULT '0' COMMENT '归一化后的Hash值',
  `sync_status` tinyint NOT NULL DEFAULT '0' COMMENT 'Redis同步状态: 0-待同步, 1-已同步',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) DEFAULT NULL COMMENT '创建人',
  `updater` varchar(64) DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除标识(0-未删除, 1-已删除)',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=373 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='正向指纹表 (白名单：标准安全拒答)';

DROP TABLE IF EXISTS `knowledge_sync_event`;
CREATE TABLE `knowledge_sync_event` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `event_id` varchar(64) NOT NULL COMMENT '事件唯一ID，用于 MQ 幂等',
  `aggregate_type` varchar(32) NOT NULL COMMENT '聚合类型：ATTACK_FEATURE、DETAIL_RULE',
  `aggregate_id` bigint NOT NULL COMMENT '聚合ID，例如 risk_attack_feature.id 或 risk_detail_rule.id',
  `operation_type` varchar(16) NOT NULL COMMENT '操作类型：CREATE、UPDATE、DELETE、REINDEX',
  `risk_details_id` bigint DEFAULT NULL COMMENT '风险小类ID',
  `content_hash` char(64) DEFAULT NULL COMMENT '内容 hash',
  `version` int NOT NULL DEFAULT '1' COMMENT '事件对应的数据版本',
  `payload` json DEFAULT NULL COMMENT '事件载荷快照',
  `es_status` tinyint NOT NULL DEFAULT '0' COMMENT 'ES处理状态：0-待处理，1-成功，2-失败',
  `milvus_status` tinyint NOT NULL DEFAULT '0' COMMENT 'Milvus处理状态：0-待处理，1-成功，2-失败',
  `pg_status` tinyint NOT NULL DEFAULT '0' COMMENT 'pg处理状态：0-待处理，1-成功，2-失败',
  `retry_count` int NOT NULL DEFAULT '0' COMMENT '重试次数',
  `next_retry_time` datetime DEFAULT NULL COMMENT '下次重试时间',
  `last_error` text COMMENT '最近一次失败原因',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_kb_sync_event_event_id` (`event_id`),
  KEY `idx_kb_sync_event_aggregate` (`aggregate_type`,`aggregate_id`),
  KEY `idx_kb_sync_event_status` (`es_status`,`milvus_status`,`next_retry_time`),
  KEY `idx_kb_sync_event_details` (`risk_details_id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='知识库-索引同步事件表';

DROP TABLE IF EXISTS `knowledge_vocabulary_keyword`;
CREATE TABLE `knowledge_vocabulary_keyword` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `group_id` bigint NOT NULL DEFAULT '1' COMMENT '所属分组ID (关联 ac_dict_group.id)',
  `risk_details_id` bigint NOT NULL COMMENT '关联31小类标签',
  `keyword` varchar(128) NOT NULL COMMENT '字面量特征词',
  `risk_level` tinyint NOT NULL DEFAULT '1' COMMENT '风险等级: 1-致命级别(命中即直接拦截), 2-疑似级别(仅打标签透传)',
  `match_type` tinyint NOT NULL DEFAULT '1' COMMENT '匹配模式: 1-精确匹配, 2-正则匹配',
  `sync_status` tinyint NOT NULL DEFAULT '0' COMMENT 'Redis同步状态: 0-待同步, 1-已同步',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) DEFAULT NULL COMMENT '创建人',
  `updater` varchar(64) DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除标识(0-未删除, 1-已删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_keyword` (`keyword`) COMMENT '保证全库特征词唯一',
  KEY `idx_sync_status` (`sync_status`) COMMENT '快速拉取待同步数据的索引'
) ENGINE=InnoDB AUTO_INCREMENT=839 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='知识库-风险词库特征词表';

DROP TABLE IF EXISTS `mock_model_output_content`;
CREATE TABLE `mock_model_output_content` (
  `id` bigint NOT NULL COMMENT 'ID',
  `bind_model_id` bigint DEFAULT NULL COMMENT '绑定模型ID',
  `output_text` longtext COMMENT '模型返回的内容(MOCK)',
  `bind_sample_id` bigint DEFAULT NULL COMMENT '绑定评测题集题目ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0-未删除，1-已删除',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='模拟大模型返回内容表，用于测试';

DROP TABLE IF EXISTS `model_info`;
CREATE TABLE `model_info` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '模型ID',
  `model` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模型名称',
  `base_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模型url',
  `api_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '应用密钥',
  `model_describe` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模型描述',
  `manufacturer_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模型厂商标识',
  `max_thread_size` bigint DEFAULT '5' COMMENT '最大并发数',
  `max_completion_tokens` bigint DEFAULT '500' COMMENT '生成词元数量',
  `stream` bit(1) DEFAULT b'0' COMMENT '流式响应 默认0，非流式',
  `status` tinyint(1) DEFAULT '1' COMMENT '状态 0 停用 1启用',
  `config` json DEFAULT NULL COMMENT '扩展配置',
  `version` bigint NOT NULL DEFAULT '1' COMMENT '版本号',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '是否删除0未删除1删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2125509333534105602 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='用户模型表';

DROP TABLE IF EXISTS `model_manufacturer`;
CREATE TABLE `model_manufacturer` (
  `ID` int NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `manufacturer_name` varchar(255) NOT NULL COMMENT '厂商名称',
  `manufacturer_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '厂商编码',
  `default_base_url` varchar(255) DEFAULT NULL COMMENT '默认BaseURL',
  `describe` varchar(255) DEFAULT NULL COMMENT '厂商信息描述',
  `icon` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '图标',
  `enable` tinyint(1) DEFAULT '1' COMMENT '是否删除0 禁用 1 启用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '是否删除0未删除 1删除',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB AUTO_INCREMENT=340979714 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='模型厂商表';

DROP TABLE IF EXISTS `risk_category`;
CREATE TABLE `risk_category` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `category_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '大类名称 (如：核心价值观与政治敏感)',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '大类描述/防范目标',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序权重 (数值越小越靠前)',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态: 0-禁用, 1-启用',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除: 0-未删除, 1-已删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_category_name` (`category_name`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='安全评测-风险大类表';

DROP TABLE IF EXISTS `risk_detail_rule`;
CREATE TABLE `risk_detail_rule` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `risk_details_id` bigint NOT NULL COMMENT '关联 risk_details.id，风险小类ID',
  `safe_threshold` decimal(3,2) NOT NULL DEFAULT '0.50' COMMENT '安全下限 (T_safe)：低于此得分判定为绝对安全，L2短路放行',
  `violation_threshold` decimal(3,2) NOT NULL DEFAULT '0.85' COMMENT '违规上限 (T_violation)：高于此得分判定为绝对违规，L2短路击毙',
  `judgment_prompt` text COMMENT '''L3 裁判宪章：该分类对应的专属 Judge LLM 判决红线提示词',
  `description` text COMMENT '业务策略解释 (如：极度敏感，错杀不漏报)',
  `version` int NOT NULL DEFAULT '1' COMMENT '规则版本，每次内容变更递增',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '业务状态：0-禁用，1-启用',
  `creator` varchar(64) DEFAULT NULL COMMENT '创建人',
  `updater` varchar(64) DEFAULT NULL COMMENT '更新人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除：0-未删除，1-已删除',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='大模型安全评测-风险小类判定规则表';

DROP TABLE IF EXISTS `risk_details`;
CREATE TABLE `risk_details` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `category_id` bigint NOT NULL COMMENT '关联的风险大类ID (对应 risk_category.id)',
  `details_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '具体风险项名称 (如：煽动颠覆/分裂国家)',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '类目内排序权重',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态: 0-禁用, 1-启用',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除: 0-未删除, 1-已删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_category_id` (`category_id`)
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='安全评测-31项风险明细项表';

DROP TABLE IF EXISTS `risk_scenario`;
CREATE TABLE `risk_scenario` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `major_category_id` bigint NOT NULL COMMENT '直属的5大类ID (与31小类解耦)',
  `scenario_code` varchar(32) NOT NULL COMMENT '场景全局唯一编码 (如: SCN-001)',
  `scenario_name` varchar(128) NOT NULL COMMENT '场景名称 (如: 虚拟货币与庞氏骗局诱导)',
  `judge_rule` text NOT NULL COMMENT '裁判系统指令(System Prompt)，包含绝对红线与豁免条件',
  `severity_level` tinyint NOT NULL DEFAULT '3' COMMENT '严重等级: 1-低, 2-中, 3-高, 4-致命',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态: 0-停用, 1-启用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `creator` varchar(64) DEFAULT NULL COMMENT '创建人',
  `updater` varchar(64) DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除标识(0-未删除, 1-已删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_scenario_code` (`scenario_code`) COMMENT '场景编码防重复',
  KEY `idx_major_category_id` (`major_category_id`) COMMENT '按大类快速拉取所有场景'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='风险场景明细表(规则父分片)';

DROP TABLE IF EXISTS `sa_chat_memory`;
CREATE TABLE `sa_chat_memory` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `session_id` varchar(100) NOT NULL COMMENT '会话 ID',
  `messages` longtext NOT NULL COMMENT '序列化的消息列表（JSON）',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_session` (`session_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='对话记忆持久化';

DROP TABLE IF EXISTS `sa_product`;
CREATE TABLE `sa_product` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '产品ID',
  `sku_code` varchar(50) NOT NULL COMMENT 'SKU编码',
  `name` varchar(200) NOT NULL COMMENT '产品名称',
  `category` varchar(50) NOT NULL COMMENT '品类：数码产品/家用电器/服装配饰/其他',
  `unit_price` decimal(10,2) NOT NULL COMMENT '售价',
  `cost` decimal(10,2) NOT NULL COMMENT '成本',
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE' COMMENT '状态：ACTIVE/INACTIVE',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `deleted` tinyint DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sku` (`sku_code`),
  KEY `idx_category` (`category`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='产品';

DROP TABLE IF EXISTS `sa_sales_order`;
CREATE TABLE `sa_sales_order` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '订单ID',
  `order_no` varchar(50) NOT NULL COMMENT '订单号',
  `rep_id` bigint NOT NULL COMMENT '销售员ID',
  `product_id` bigint NOT NULL COMMENT '产品ID',
  `region_id` bigint NOT NULL COMMENT '销售大区ID',
  `customer_name` varchar(100) NOT NULL COMMENT '客户名称',
  `quantity` int NOT NULL COMMENT '销售数量',
  `unit_price` decimal(10,2) NOT NULL COMMENT '成交单价',
  `amount` decimal(12,2) NOT NULL COMMENT '成交金额（quantity * unit_price）',
  `cost` decimal(12,2) NOT NULL COMMENT '成本总额',
  `profit` decimal(12,2) NOT NULL COMMENT '毛利（amount - cost）',
  `status` varchar(20) NOT NULL DEFAULT 'COMPLETED' COMMENT '状态：COMPLETED/REFUNDED/CANCELLED',
  `order_date` date NOT NULL COMMENT '下单日期',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `deleted` tinyint DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_order_no` (`order_no`),
  KEY `idx_rep` (`rep_id`),
  KEY `idx_product` (`product_id`),
  KEY `idx_region` (`region_id`),
  KEY `idx_order_date` (`order_date`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=70 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='销售订单';

DROP TABLE IF EXISTS `sa_sales_region`;
CREATE TABLE `sa_sales_region` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '大区ID',
  `name` varchar(50) NOT NULL COMMENT '大区名称，如：华东区',
  `parent_region_id` bigint DEFAULT NULL COMMENT '上级大区，NULL表示顶级',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `deleted` tinyint DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='销售大区';

DROP TABLE IF EXISTS `sa_sales_rep`;
CREATE TABLE `sa_sales_rep` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '销售员ID',
  `name` varchar(50) NOT NULL COMMENT '姓名',
  `region_id` bigint NOT NULL COMMENT '所属大区',
  `role` varchar(20) NOT NULL DEFAULT 'SALES_REP' COMMENT '角色：SALES_REP/SALES_MANAGER/SALES_DIRECTOR',
  `email` varchar(100) DEFAULT NULL COMMENT '邮箱',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `deleted` tinyint DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_region` (`region_id`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='销售员';

DROP TABLE IF EXISTS `t_user`;
CREATE TABLE `t_user` (
  `id` varchar(20) NOT NULL COMMENT '主键ID',
  `username` varchar(64) NOT NULL COMMENT '用户名，唯一',
  `password` varchar(128) NOT NULL COMMENT '密码',
  `role` varchar(32) NOT NULL COMMENT '角色：admin/user',
  `avatar` text COMMENT '用户头像',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` smallint DEFAULT NULL COMMENT '是否删除 0：正常 1：删除',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='系统用户表';
SET FOREIGN_KEY_CHECKS = 1;
